const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Medina, Saudi Arabia approximate coordinates
    const medinaPoint = ee.Geometry.Point(39.6083, 24.4714);
    const geometry = medinaPoint.buffer(20000); // 20km buffer around the city center

    const dateRange1 = ee.DateRange('1984-05-01', '1984-07-31'); // June 1984
    const dateRange2 = ee.DateRange('2018-06-01', '2018-08-31'); // July 2018

    // Cloud masking function for Landsat SR collections
    function maskL8Sr(image) {
      const qa = image.select('QA_PIXEL');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 4); // Bit 4 for cloud shadow
      const cloudsBitMask = (1 << 3);    // Bit 3 for clouds (Landsat 8 SR)
      // Bits 3, 5 for Landsat 5/7 SR are clouds and cloud shadow.
      // For Landsat 8 SR, QA_PIXEL bit 3 is cloud, bit 4 is cloud shadow.
      // For Landsat 5 TM, QA_PIXEL bit 5 is cloud, bit 3 is cloud shadow.
      // Let's create a robust mask for both:
      const cirrusBitMask = (1 << 2); // Cirrus
      const clearBitMask = (1 << 6); // Clear land
      const waterBitMask = (1 << 7); // Water

      // Select pixels that are not clouds, not cloud shadow, and not cirrus.
      // Also include pixels identified as "clear"
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      // Additionally, only keep pixels where the 'clear' bit is set OR where it's not water.
      // This helps filter out bad quality and focuses on land.
      const clear = qa.bitwiseAnd(clearBitMask).neq(0);
      const notWater = qa.bitwiseAnd(waterBitMask).eq(0);

      // Apply scaled reflectance and add original metadata.
      const opticalBands = image.select('SR_B[1-7]').multiply(0.0000275).add(-0.2);
      return image.addBands(opticalBands, null, true)
                  .updateMask(mask.and(clear).and(notWater))
                  .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDBI
    function calculateNDBI(image, sensor) {
      let swir1, nir;
      if (sensor === 'L5') {
        swir1 = image.select('SR_B5'); // Landsat 5 SWIR1
        nir = image.select('SR_B4');  // Landsat 5 NIR
      } else if (sensor === 'L8') {
        swir1 = image.select('SR_B6'); // Landsat 8 SWIR1
        nir = image.select('SR_B5');  // Landsat 8 NIR
      } else {
        throw new Error('Unsupported sensor type for NDBI calculation.');
      }
      return image.normalizedDifference([swir1.name(), nir.name()]).rename('NDBI');
    }

    // Function to get urban area in km^2
    function getUrbanArea(image, geometry, scale, ndbiThreshold = 0) {
      const urbanMask = image.select('NDBI').gt(ndbiThreshold);
      const urbanPixels = urbanMask.multiply(ee.Image.pixelArea()).divide(1e6); // Convert m^2 to km^2

      return urbanPixels.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDBI');
    }

    // 2. Data Acquisition & Check
    // Landsat 5 TM Collection for 1984
    let collection1_L5 = ee.ImageCollection('LANDSAT/LT05/C02/SR')
      .filterBounds(geometry)
      .filterDate(dateRange1.start(), dateRange1.end())
      .map(maskL8Sr) // Use maskL8Sr, it generally works for L5 SR too (though bits might differ slightly, it captures common clouds/shadows)
      .median();

    let collection1_L5_size = await ee.ImageCollection('LANDSAT/LT05/C02/SR')
      .filterBounds(geometry)
      .filterDate(dateRange1.start(), dateRange1.end()).size().getInfo();

    if (collection1_L5_size === 0) {
      console.log("No Landsat 5 data for 1984. Trying Landsat 4 if available.");
      let collection1_L4 = ee.ImageCollection('LANDSAT/LT04/C02/SR')
        .filterBounds(geometry)
        .filterDate(dateRange1.start(), dateRange1.end())
        .map(maskL8Sr)
        .median();
      let collection1_L4_size = await ee.ImageCollection('LANDSAT/LT04/C02/SR')
        .filterBounds(geometry)
        .filterDate(dateRange1.start(), dateRange1.end()).size().getInfo();
      if (collection1_L4_size === 0) {
        console.log("No Landsat 4 data for 1984 either.");
        console.log("C1");
        return;
      } else {
        collection1_L5 = collection1_L4; // Use L4 if L5 is empty
        console.log(`1984 Images (L4): ${collection1_L4_size}`);
      }
    } else {
      console.log(`1984 Images (L5): ${collection1_L5_size}`);
    }

    // Landsat 8 OLI Collection for 2018
    const collection2 = ee.ImageCollection('LANDSAT/LC08/C02/SR')
      .filterBounds(geometry)
      .filterDate(dateRange2.start(), dateRange2.end())
      .map(maskL8Sr)
      .median();

    const collection2_size = await ee.ImageCollection('LANDSAT/LC08/C02/SR')
      .filterBounds(geometry)
      .filterDate(dateRange2.start(), dateRange2.end()).size().getInfo();

    if (collection2_size === 0) {
      console.log("No Landsat 8 data for 2018. Trying Landsat 7.");
      let collection2_L7 = ee.ImageCollection('LANDSAT/LE07/C02/SR')
        .filterBounds(geometry)
        .filterDate(dateRange2.start(), dateRange2.end())
        .map(maskL8Sr)
        .median();
      let collection2_L7_size = await ee.ImageCollection('LANDSAT/LE07/C02/SR')
        .filterBounds(geometry)
        .filterDate(dateRange2.start(), dateRange2.end()).size().getInfo();
      if (collection2_L7_size === 0) {
        console.log("No Landsat 7 data for 2018 either.");
        console.log("C1");
        return;
      } else {
        collection2 = collection2_L7; // Use L7 if L8 is empty
        console.log(`2018 Images (L7): ${collection2_L7_size}`);
      }
    } else {
      console.log(`2018 Images (L8): ${collection2_size}`);
    }

    // Ensure the resulting images are not null after median reduction
    const hasData1 = await ee.Image(collection1_L5.select('SR_B4')).reduceRegion({
      reducer: ee.Reducer.count(), geometry: geometry, scale: 300, maxPixels: 1e9
    }).get('SR_B4').getInfo();
    if (hasData1 === 0) {
      console.log("1984: No valid pixels after masking.");
      console.log("C2");
      return;
    }

    const hasData2 = await ee.Image(collection2.select('SR_B5')).reduceRegion({
      reducer: ee.Reducer.count(), geometry: geometry, scale: 300, maxPixels: 1e9
    }).get('SR_B5').getInfo();
    if (hasData2 === 0) {
      console.log("2018: No valid pixels after masking.");
      console.log("C2");
      return;
    }

    // 3. Processing & Calculation
    const ndbi1984 = calculateNDBI(collection1_L5, (collection1_L5_size > 0 ? 'L5' : 'L4')); // Pass the correct sensor for band names
    const ndbi2018 = calculateNDBI(collection2, (collection2_size > 0 ? 'L8' : 'L7'));

    // Use a relatively coarse scale for reduction to avoid memory issues and speed up.
    // Urban areas are large, so 100m or 300m is acceptable for total area.
    const reductionScale = 100; // meters

    const urbanArea1984_val = await getUrbanArea(ndbi1984, geometry, reductionScale, 0).getInfo(); // NDBI > 0
    const urbanArea2018_val = await getUrbanArea(ndbi2018, geometry, reductionScale, 0).getInfo(); // NDBI > 0

    // 4. Validation & Final Answer
    if (urbanArea1984_val === null || urbanArea2018_val === null ||
        isNaN(urbanArea1984_val) || isNaN(urbanArea2018_val)) {
      console.log("C3"); // Calculation failure (None or NaN result)
      return;
    }

    console.log(`Urban area 1984: ${urbanArea1984_val.toFixed(2)} km^2`);
    console.log(`Urban area 2018: ${urbanArea2018_val.toFixed(2)} km^2`);

    if (urbanArea2018_val > urbanArea1984_val) {
      console.log("A"); // Yes, urban area expanded
    } else {
      console.log("B"); // No, urban area did not expand or shrunk
    }

  } catch (e) {
    console.error("An error occurred: ", e);
    console.log("D"); // General error, potentially syntax or method error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
